            { "symbol", getValue(market, "id") },
        };
        object response = await this.publicGetPublicApiMarketV1Ticker24hr(this.extend(request, parameters));
        //
        //     {
        //         "data": [
        //             {
        //                 "symbol": "BTC-PERP-USDT",
        //                 "lastPrice": "63790.1",
        //                 "openPrice": "63808.3",
        //                 "highPrice": "64446.7",
        //                 "lowPrice": "63289.7",
        //                 "amount": "789198764",
        //                 "volume": "502595131.844331",
        //                 "openTime": 1786514400,
        //                 "closeTime": 1786602644,
        //                 "priceChange": "-18.2",
        //                 "priceChangePercent": "0",
        //                 "prevClosePrice": "63842.4",
        //                 "bidPrice": "63790",
        //                 "bidQty": "222000",
        //                 "askPrice": "63790.2",
        //                 "askQty": "255355",
        //                 "openInterest": "29489680",
        //                 "fundingRate": "0.0001",
        //                 "nextFundingTime": 1786608000000,
        //                 "fundingIntervalMinutes": 480
        //             }
        //         ],
        //         "code": 1,
        //         "msg": "Success",
        //         "success": true,
        //         "time": 1786602644221
        //     }
        //
        // a single-symbol query returns data as one object, a multi-symbol or bare query returns an array
        object data = this.safeDict(response, "data");
        if (isTrue(isEqual(data, null)))
        {
            object rows = this.safeList(response, "data", new List<object>() {});
            data = this.safeDict(rows, 0, new Dictionary<string, object>() {});
        }
        return ccxt.BaseExchange.ToTicker(this.parseTicker(data, market));
