    public override object parseFundingRate(object contract, object market = null)
    {
        //
        // ticker/24hr contract rows
        //     {
        //         "symbol": "ETH-PERP-USDT",
        //         "lastPrice": "1896.17",
        //         "openPrice": "1887.07",
        //         "highPrice": "1924",
        //         "lowPrice": "1872.44",
        //         "amount": "1937140691",
        //         "volume": "366459222.269293",
        //         "openTime": 1786518000,
        //         "closeTime": 1786607054,
        //         "priceChange": "9.1",
        //         "priceChangePercent": "0.005",
        //         "prevClosePrice": "1897.71",
        //         "bidPrice": "1896",
        //         "bidQty": "105",
        //         "askPrice": "1896.01",
        //         "askQty": "11354",
        //         "openInterest": "19344237",
        //         "fundingRate": "0.00006016",
        //         "nextFundingTime": 1786608000000,
        //         "fundingIntervalMinutes": 480
        //     }
        //
        string? marketId = this.safeString(contract, "symbol");
        market = this.safeMarket(marketId, market);
        object timestamp = this.safeTimestamp(contract, "closeTime");
        // dated futures carry a zero nextFundingTime as funding only applies to
        // perpetuals, observed live, the zero means no next funding and is omitted
        object nextFundingTimestamp = this.safeIntegerOmitZero(contract, "nextFundingTime");
        Int64? fundingIntervalMinutes = this.safeInteger(contract, "fundingIntervalMinutes");
        object interval = null;
        // a wire value of zero minutes reaches this, and zero hours is not an
        // interval: a caller annualising a rate divides by it. anything under an
        // hour rounds to the same string, and the vocabulary has no minutes
        if (isTrue(isTrue((!isEqual(fundingIntervalMinutes, null))) && isTrue((isGreaterThanOrEqual(fundingIntervalMinutes, 60)))))
        {
            object hours = this.parseToInt(divide(fundingIntervalMinutes, 60));
            interval = add(((object)hours).ToString(), "h");
        }
        return new Dictionary<string, object>() {
            { "info", contract },
            { "symbol", getValue(market, "symbol") },
            { "markPrice", null },
            { "indexPrice", null },
            { "interestRate", null },
            { "estimatedSettlePrice", null },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "fundingRate", this.safeNumber(contract, "fundingRate") },
            { "fundingTimestamp", null },
            { "fundingDatetime", null },
            { "nextFundingRate", null },
            { "nextFundingTimestamp", nextFundingTimestamp },
            { "nextFundingDatetime", this.iso8601(nextFundingTimestamp) },
            { "previousFundingRate", null },
            { "previousFundingTimestamp", null },
            { "previousFundingDatetime", null },
            { "interval", interval },
        };
    }

    /**
     * @method
     * @name btse#fetchTrades
     * @description get the list of most recent trades for a particular symbol
     * @see https://docs.btse.com/markets/rest/get-trades/
     * @param {string} symbol unified symbol of the market to fetch trades for
     * @param {int} [since] timestamp in ms of the earliest trade to fetch, applied client-side to the most recent trades window
     * @param {int} [limit] the maximum amount of trades to fetch (max 500)
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest entry to fetch, applied client-side to the most recent trades window
     * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
     */
    public async override Task<List<ccxt.Trade>> FetchTrades(string symbol, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        object market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbol", getValue(market, "id") },
        };
        if (isTrue(!isEqual(limit, null)))
        {
            ((IDictionary<string,object>)request)["limit"] = mathMin(limit, 500); // the endpoint supports a maximum of 500 trades
        }
        // the unified trades endpoint has no server-side time filtering, since and until are applied client-side below
        object until = null;
        var untilparametersVariable = this.handleOptionAndParams(parameters, "fetchTrades", "until");
        until = ((IList<object>)untilparametersVariable)[0];
        parameters = ((IList<object>)untilparametersVariable)[1];
        object response = await this.publicGetPublicApiMarketV1Trades(this.extend(request, parameters));
        //
        //     {
        //         "data": [
        //             {
        //                 "id": 91151062,
        //                 "timestamp": 1786605669577,
        //                 "price": "1896.3291755587",
        //                 "size": "0.06",
        //                 "quoteSize": "113.7797505335",
        //                 "side": "BUY"
        //             }
        //         ],
        //         "code": 1,
        //         "msg": "Success",
        //         "success": true,
        //         "time": 1786605671650
        //     }
        //
        object data = this.safeList(response, "data", new List<object>() {});
        object trades = this.parseTrades(data, market, since, limit);
        if (isTrue(isEqual(until, null)))
        {
            return ccxt.BaseExchange.ToTradeList(trades);
        }
        List<object> result = new List<object>() {};
        for (object i = 0; isLessThan(i, getArrayLength(trades)); postFixIncrement(ref i))
        {
            object trade = getValue(trades, i);
            Int64? timestamp = this.safeInteger(trade, "timestamp");
            if (isTrue(isTrue((isEqual(timestamp, null))) || isTrue((isLessThanOrEqual(timestamp, until)))))
            {
                ((IList<object>)result).Add(trade);
            }
        }
        return ccxt.BaseExchange.ToTradeList(result);
    }

    /**
     * @method
     * @name btse#fetchMyTrades
     * @description fetch all trades made by the user
     * @see https://docs.btse.com/spot/rest/get-trade-history/
     * @see https://docs.btse.com/futures/rest/get-trade-history/
     * @param {string} [symbol] unified market symbol
     * @param {int} [since] the earliest time in ms to fetch trades for
     * @param {int} [limit] the maximum number of trades structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms for the ending date filter, default is undefined
     * @param {string} [params.type] 'spot' or 'swap' or 'future', default is 'spot'
     * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/#/?id=trade-structure}
     */
    public async override Task<List<ccxt.Trade>> FetchMyTrades(string symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        object paginate = this.safeBool(parameters, "paginate", false);
        if (isTrue(isEqual(paginate, true)))
        {
            parameters = this.omit(parameters, "paginate");
            return ccxt.BaseExchange.ToTradeList(await this.fetchPaginatedCallDynamic("fetchMyTrades", symbol, since, limit, parameters));
        }
        object market = null;
        object request = new Dictionary<string, object>() {};
        if (isTrue(!isEqual(symbol, null)))
        {
            market = this.market(symbol);
            ((IDictionary<string,object>)request)["symbol"] = getValue(market, "id");
        }
        if (isTrue(!isEqual(since, null)))
        {
            ((IDictionary<string,object>)request)["startTime"] = since;
        }
        if (isTrue(!isEqual(limit, null)))
        {
            ((IDictionary<string,object>)request)["count"] = limit;
        }
        var requestparametersVariable = this.handleUntilOption("endTime", request, parameters);
        request = ((IList<object>)requestparametersVariable)[0];
        parameters = ((IList<object>)requestparametersVariable)[1];
        object marketType = "spot";
        var marketTypeparametersVariable = this.handleMarketTypeAndParams("fetchMyTrades", market, parameters, marketType);
        marketType = ((IList<object>)marketTypeparametersVariable)[0];
        parameters = ((IList<object>)marketTypeparametersVariable)[1];
        object response = null;
        if (isTrue(isEqual(marketType, "spot")))
        {
            if (isTrue(isEqual(symbol, null)))
            {
                throw new ArgumentsRequired ((string)add(this.id, " fetchMyTrades() requires a symbol argument for spot markets")) ;
            }
            //
            //     {
            //         "data": [
            //             {
            //                 "serialId": 375599088,
            //                 "tradeId": "de1a79b8-f408-4e05-b8b7-7ed3c4e86542",
            //                 "orderId": "6c72d906-cb8f-469c-8ab0-b97bc8dff9c2",
            //                 "clOrderId": null,
            //                 "symbol": "BTC-USD",
            //                 "base": "BTC",
            //                 "quote": "USD",
            //                 "orderSide": "BUY",
            //                 "orderType": 77,
            //                 "triggerType": 0,
            //                 "triggerPrice": 0,
            //                 "price": 64235.97008,
            //                 "size": 1.9,
            //                 "filledSize": 0.00002,
            //                 "feeCurrency": "BTC",
            //                 "feeAmount": 1e-8,
            //                 "timestamp": 1784890959551
            //             }
            //         ],
            //         "code": 1,
            //         "msg": "Success",
            //         "success": true,
            //         "time": 1786610160164
            //     }
            //
            response = await this.privateGetSpotApiV4TradeTradeHistory(this.extend(request, parameters));
        } else
        {
            // the futures endpoint does not support a count parameter, the limit is applied client-side
            request = this.omit(request, "count");
            if (isTrue(!isEqual(market, null)))
            {
                ((IDictionary<string,object>)request)["symbol"] = this.futuresRequestId(market);
            }
            //
            //     {
            //         "data": [
            //             {
            //                 "tradeId": "1ad38104-6248-4a45-bc56-5fa9bf7f3868",
            //                 "orderId": "8ad94105-8cce-4e01-86b8-2d0fb403db66",
            //                 "clOrderId": "",
            //                 "positionId": "BTC-PERP-USDT",
            //                 "orderSide": "BUY",
            //                 "type": 77,
            //                 "orderDetailType": null,
            //                 "price": 0,
            //                 "size": 1,
            //                 "avgFilledPrice": 60010,
            //                 "filledSize": 1,
            //                 "triggerPrice": 0,
            //                 "contractSize": 0.00001,
            //                 "base": "BTC",
            //                 "quote": "USDT",
            //                 "symbol": "BTC-PERP",
            //                 "wallet": "BTC-PERP Isolated Wallet",
            //                 "feeCurrency": "USDT",
            //                 "feeAmount": 0.00012002,
            //                 "realizedPnl": 0,
            //                 "total": -0.00012002,
            //                 "serialId": 375598162,
            //                 "timestamp": 1784882344446
            //             }
            //         ],
            //         "code": 1,
            //         "msg": "Success",
            //         "success": true,
            //         "time": 1786610160164
            //     }
            //
            response = await this.privateGetFuturesApiV3TradeTradeHistory(this.extend(request, parameters));
        }
        object rows = ((object)this.safeList(response, "data"));
        if (isTrue(isEqual(rows, null)))
        {
            rows = response;
        }
        return ccxt.BaseExchange.ToTradeList(this.parseTrades(rows, market, since, limit));
    }

    /**
     * @method
     * @name btse#fetchOrderTrades
     * @description fetch all the trades made from a single order
     * @see https://btsecom.github.io/docs/spotV3_3/en/#query-user-trades-fills
     * @see https://btsecom.github.io/docs/futuresV2_3/en/#query-trades-fills-2
     * @param {string} id order id
     * @param {string} [symbol] unified market symbol
     * @param {int} [since] the earliest time in ms to fetch trades for
     * @param {int} [limit] the maximum number of trades to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.clientOrderId] client order id, could be used instead of the order id
     * @param {string} [params.type] 'spot' or 'swap' or 'future', default is 'spot'
     * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
     */
    public async override Task<List<ccxt.Trade>> FetchOrderTrades(string id, string symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        string? clientOrderId = this.safeString(parameters, "clientOrderId");
        if (isTrue(isEqual(clientOrderId, null)))
        {
            if (isTrue(isEqual(id, null)))
            {
                throw new ArgumentsRequired ((string)add(this.id, " fetchOrderTrades() requires an id argument or a clientOrderId parameter")) ;
            } else
            {
                parameters = this.extend(parameters, new Dictionary<string, object>() {
                    { "orderID", id },
                });
