    public override object parseOrder(object order, object market = null)
    {
        //
        // createOrder - spot
        //     {
        //         "status": 2,
        //         "symbol": "ETH-USDT",
        //         "orderType": 76,
        //         "price": 1000,
        //         "side": "BUY",
        //         "orderID": "cde4fb37-2e2b-437e-a816-4b55b2e2b7c7",
        //         "timestamp": 1770813053751,
        //         "triggerPrice": 0,
        //         "stopPrice": null,
        //         "trigger": false,
        //         "message": "",
        //         "clOrderID": null,
        //         "stealth": 1,
        //         "deviation": 1,
        //         "postOnly": false,
        //         "orderDetailType": null,
        //         "originalOrderBaseSize": 0.0001,
        //         "originalOrderQuoteSize": null,
        //         "currentOrderBaseSize": 0.0001,
        //         "currentOrderQuoteSize": null,
        //         "remainingOrderBaseSize": 0.0001,
        //         "remainingOrderQuoteSize": null,
        //         "filledBaseSize": 0,
        //         "totalFilledBaseSize": 0,
        //         "orderCurrency": "base",
        //         "avgFilledPrice": 0,
        //         "time_in_force": "GTC"
        //     }
        //
        // createOrder - swap
        //     {
        //         "status": 4,
        //         "symbol": "ETH-PERP",
        //         "orderType": 77,
        //         "price": 1956.59,
        //         "side": "BUY",
        //         "orderID": "5c6a26db-8cfb-45c7-b25d-56927bc36795",
        //         "timestamp": 1770821231984,
        //         "triggerPrice": 0,
        //         "trigger": false,
        //         "deviation": 100,
        //         "stealth": 100,
        //         "message": "",
        //         "avgFilledPrice": 1956.59,
        //         "clOrderID": "",
        //         "originalOrderSize": 1,
        //         "currentOrderSize": 1,
        //         "filledSize": 1,
        //         "totalFilledSize": 1,
        //         "remainingSize": 0,
        //         "postOnly": false,
        //         "orderDetailType": null,
        //         "positionMode": "ONE_WAY",
        //         "positionDirection": null,
        //         "positionId": "ETH-PERP-USDT",
        //         "time_in_force": "GTC"
        //     }
        //
        string? marketId = this.safeString2(order, "symbol", "market");
        market = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger(order, "timestamp");
        // open_orders rows carry no numeric status - the state lives in
        // orderState (STATUS_ACTIVE / STATUS_INACTIVE), and time_in_force
        // is spelled timeInForce there (observed live), so both fall back
        string? rawStatus = this.safeString2(order, "status", "orderState");
        string? rawType = this.safeString2(order, "orderType", "type");
        object status = this.parseOrderStatus(rawStatus);
        object orderType = this.parseOrderType(rawType);
        if (isTrue(isTrue((isEqual(orderType, "market"))) && isTrue((isEqual(status, "open")))))
        {
            // market orders never rest on the book, the exchange reports the
            // partially filled code on them when a residual quote dust amount
            // cannot fill, observed live, such orders are finished
            status = "closed";
        }
        string? rawTimeInForce = this.safeString2(order, "time_in_force", "timeInForce");
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "id", this.safeString2(order, "orderID", "orderId") },
            { "clientOrderId", this.safeString2(order, "clOrderID", "clOrderId") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "lastUpdateTimestamp", null },
            { "status", status },
            { "symbol", getValue(market, "symbol") },
            { "type", orderType },
            { "timeInForce", this.parseTimeInForce(rawTimeInForce) },
            { "postOnly", this.safeBool(order, "postOnly") },
            { "reduceOnly", this.safeBool(order, "reduceOnly") },
            { "side", this.safeStringLower2(order, "side", "orderSide") },
            { "price", this.safeString2(order, "price", "orderPrice") },
            { "triggerPrice", this.omitZero(this.safeString2(order, "triggerOriginalPrice", "triggerPrice")) },
            { "stopLossPrice", null },
            { "takeProfitPrice", null },
            { "amount", this.safeStringN(order, new List<object>() {"currentOrderBaseSize", "currentOrderSize", "orderSize"}) },
            { "filled", this.safeStringN(order, new List<object>() {"totalFilledBaseSize", "totalFilledSize", "filledSize"}) },
            { "remaining", this.safeString2(order, "remainingOrderBaseSize", "remainingSize") },
            { "cost", null },
            { "trades", null },
            { "fee", null },
            { "average", this.omitZero(this.safeString2(order, "avgFilledPrice", "averageFillPrice")) },
        }, market);
    }

    public virtual object parseOrderStatus(object status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "2", "open" },
            { "3", "closed" },
            { "4", "closed" },
            { "5", "open" },
            { "6", "canceled" },
            { "7", "refunded" },
            { "8", "rejected" },
            { "9", "open" },
            { "10", "open" },
            { "15", "rejected" },
            { "16", "rejected" },
            { "17", "rejected" },
            { "123", "open" },
            { "STATUS_ACTIVE", "open" },
            { "STATUS_INACTIVE", "canceled" },
            { "ORDER_INSERTED", "open" },
            { "ORDER_PARTIALLY_TRANSACTED", "open" },
            { "ORDER_FULLY_TRANSACTED", "closed" },
            { "ORDER_CANCELLED", "canceled" },
        };
        return this.safeString(statuses, status, status);
    }

    public virtual object parseOrderType(object type)
    {
        Dictionary<string, object> types = new Dictionary<string, object>() {
            { "76", "limit" },
            { "77", "market" },
            { "80", "limit" },
        };
        return this.safeString(types, type, type);
    }

    public virtual object parseTimeInForce(object timeInForce)
    {
        Dictionary<string, object> values = new Dictionary<string, object>() {
            { "GTC", "GTC" },
            { "IOC", "IOC" },
            { "FOK", "FOK" },
            { "HALFSEC", "GTD" },
            { "HALFMIN", "GTD" },
            { "FIVEMIN", "GTD" },
            { "HOUR", "GTD" },
            { "TWELVEHOUR", "GTD" },
            { "DAY", "GTD" },
            { "WEEK", "GTD" },
            { "MONTH", "GTD" },
        };
        return this.safeString(values, timeInForce, timeInForce);
    }

    /**
     * @method
     * @name btse#fetchTradingFees
     * @description fetch the trading fees for multiple markets
     * @see https://docs.btse.com/spot/rest/get-fees
     * @see https://btsecom.github.io/docs/futuresV2_3/en/#query-account-fee
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.type] 'spot', 'swap' or 'future' (default is 'spot')
     * @returns {object} a dictionary of [fee structures]{@link https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
     */
    public async override Task<ccxt.TradingFees> FetchTradingFees(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        object response = null;
        object marketType = "spot";
        var marketTypeparametersVariable = this.handleMarketTypeAndParams("fetchTradingFees", null, parameters, marketType);
        marketType = ((IList<object>)marketTypeparametersVariable)[0];
        parameters = ((IList<object>)marketTypeparametersVariable)[1];
        if (isTrue(isEqual(marketType, "spot")))
        {
            response = await this.privateGetSpotApiV4TradeFees(parameters);
        } else
        {
            // the futures fees stay on the legacy endpoint, the unified futures
            // api has no fees route
            response = await this.privateGetFuturesApiV23UserFees(parameters);
        }
        //
        //     [
        //         {
        //             "symbol": "FUSD-USD",
        //             "makerFee": 0.002,
        //             "takerFee": 0.002
        //         }
        //     ]
        //
        object rows = this.safeList(response, "data", ((object)response));
        object responseList = this.arrayConcat(new List<object>() {}, rows);
        Dictionary<string, object> result = new Dictionary<string, object>() {};
        for (object i = 0; isLessThan(i, getArrayLength(responseList)); postFixIncrement(ref i))
        {
            object feeInfo = getValue(responseList, i);
            string? marketId = this.safeString(feeInfo, "symbol");
            object market = this.safeMarket(marketId);
            object symbol = getValue(market, "symbol");
            object makerFee = this.safeNumber(feeInfo, "makerFee");
            object takerFee = this.safeNumber(feeInfo, "takerFee");
            ((IDictionary<string,object>)result)[(string)symbol] = new Dictionary<string, object>() {
                { "info", feeInfo },
                { "symbol", symbol },
                { "maker", makerFee },
                { "taker", takerFee },
                { "percentage", true },
                { "tierBased", true },
            };
        }
        return ccxt.BaseExchange.ToTradingFees(result);
    }

    public async virtual Task<object> requestWalletHistoryRows(object methodName, object historyTypes, object code = null, object since = null, object limit = null, object parameters = null)
    {
        // the helper always receives a non empty history type list, the list is
        // rebuilt through safeList so the transpilers treat it as an array in
        // every runtime
        parameters ??= new Dictionary<string, object>();
        object typesList = this.safeList(new Dictionary<string, object>() {
            { "types", historyTypes },
        }, "types", new List<object>() {});
        await this.loadMarkets();
        string? walletType = this.safeString(parameters, "walletType", "SPOT");
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "walletType", walletType },
        };
        // the endpoint applies a server side history type filter sent as a
        // json encoded array in the query string, verified live
        ((IDictionary<string,object>)request)["historyTypes"] = this.json(typesList);
        parameters = this.omit(parameters, "walletType");
        object currency = null;
        if (isTrue(!isEqual(code, null)))
        {
            currency = this.currency(code);
            ((IDictionary<string,object>)request)["asset"] = getValue(currency, "id");
        } else if (isTrue(isEqual(walletType, "SPOT")))
        {
            throw new ArgumentsRequired ((string)add(add(add(this.id, " "), methodName), "() requires a code argument for the spot wallet history")) ;
        }
        if (isTrue(!isEqual(since, null)))
        {
            ((IDictionary<string,object>)request)["startTime"] = since;
        }
        if (isTrue(!isEqual(limit, null)))
        {
            ((IDictionary<string,object>)request)["pageSize"] = limit;
        }
        object until = null;
        var untilparametersVariable = this.handleOptionAndParams(parameters, methodName, "until");
        until = ((IList<object>)untilparametersVariable)[0];
        parameters = ((IList<object>)untilparametersVariable)[1];
        if (isTrue(!isEqual(until, null)))
        {
            ((IDictionary<string,object>)request)["endTime"] = until;
        }
        object response = await this.privateGetPublicApiWalletV1UserWalletHistory(this.extend(request, parameters));
        //
        //     {
        //         "code": 1,
        //         "msg": "Success",
        //         "time": 1786624541092,
        //         "data": [
        //             {
        //                 "transactionTime": 1786510157962,
        //                 "type": "DEPOSIT",
        //                 "walletName": "SPOT@",
        //                 "asset": "USDT",
        //                 "netAmount": "100",
        //                 "amount": "100",
        //                 "transactionRef": "2026081200000367",
        //                 "status": "COMPLETED",
        //                 "description": null,
        //                 "fees": "0",
        //                 "cryptoNetwork": "ERC20",
        //                 "toAddress": "0x36bd7cbc486658c9777672fe742971bda65d5e6f",
        //                 "confirmTimes": "(15/15)",
        //                 "txId": "0xb4d88986d013f799d78e6232792c44b45dff1213a015171ddcf4adfcd283b3fd"
        //             }
        //         ],
        //         "success": true
        //     }
        //
        object rawRows = this.safeList(response, "data", ((object)response));
        // the requested types are also filtered client side over both the legacy
        // and the unified enum vocabularies as the legacy endpoint ignored the
        // filter and returned the whole mixed ledger
        Dictionary<string, object> allowed = new Dictionary<string, object>() {};
        for (object i = 0; isLessThan(i, getArrayLength(typesList)); postFixIncrement(ref i))
        {
            object historyType = getValue(typesList, i);
            ((IDictionary<string,object>)allowed)[(string)historyType] = true;
            ((IDictionary<string,object>)allowed)[(string)this.capitalize(((string)historyType).ToLower())] = true;
        }
        List<object> rows = new List<object>() {};
        for (object i = 0; isLessThan(i, getArrayLength(rawRows)); postFixIncrement(ref i))
        {
            object entry = getValue(rawRows, i);
            string? type = this.safeString(entry, "type", "");
            if (isTrue(inOp(allowed, type)))
            {
                ((IList<object>)rows).Add(entry);
            }
        }
        return ((object)new List<object>() {rows, currency});
    }

