    public override object parseTransaction(object transaction, object currency = null)
    {
        //
        //     {
        //         "username": "user",
        //         "orderId": "2026081200000367",
        //         "wallet": "SPOT@",
        //         "currency": "USDT",
        //         "type": "Deposit",
        //         "amount": 100,
        //         "fees": 0,
        //         "description": "",
        //         "timestamp": 1786510157962,
        //         "status": "PROCESSING",
        //         "txId": "",
        //         "toAddress": "0x0000000000000000000000000000000000000000",
        //         "currencyNetwork": "",
        //         "sourceCurrency": "USDT",
        //         "sourceAmount": 0,
        //         "targetCurrency": "",
        //         "targetAmount": 0,
        //         "rate": 0
        //     }
        //
        string? currencyId = this.safeString2(transaction, "currency", "asset");
        object code = this.safeCurrencyCode(currencyId, currency);
        object timestamp = this.safeInteger2(transaction, "timestamp", "transactionTime");
        string? networkId = this.safeString2(transaction, "currencyNetwork", "cryptoNetwork");
        return new Dictionary<string, object>() {
            { "info", transaction },
            { "id", this.safeString2(transaction, "orderId", "transactionRef") },
            { "txid", this.safeString(transaction, "txId") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "network", this.networkIdToCode(networkId, code) },
            { "address", this.safeString(transaction, "toAddress") },
            { "addressTo", this.safeString(transaction, "toAddress") },
            { "addressFrom", null },
            { "tag", null },
            { "tagTo", null },
            { "tagFrom", null },
            { "type", this.parseTransactionType(this.safeString(transaction, "type")) },
            { "amount", this.safeNumber(transaction, "amount") },
            { "currency", code },
            { "status", this.parseTransactionStatus(this.safeString(transaction, "status")) },
            { "updated", null },
            { "internal", null },
            { "comment", this.safeString(transaction, "description") },
            { "fee", new Dictionary<string, object>() {
                { "currency", code },
                { "cost", this.safeNumber2(transaction, "fees", "fee") },
            } },
        };
    }

    public virtual object parseTransactionType(object type)
    {
        Dictionary<string, object> types = new Dictionary<string, object>() {
            { "Deposit", "deposit" },
